import {Dictation} from './voice.js';
const $=id=>document.getElementById(id);
export function createDictationTools({insertText,saveSelection,isRecording,notify,save}){
  let active=false;const supported=!!(globalThis.SpeechRecognition||globalThis.webkitSpeechRecognition),fail=text=>{$('dictation-error').textContent=text;$('dictation-error').hidden=!text;};
  const errors={'not-allowed':'Microphone or speech access was not allowed. Enable it in your browser’s site settings, or keep typing.','audio-capture':'No microphone is available. Connect one or use your keyboard’s dictation.','network':'The speech service could not be reached. Your existing text is safe. Check your connection and try again.','no-speech':'No speech was detected. Try again when you are ready.','language-not-supported':'This language is unavailable in your browser’s speech service. Try another English option.','service-not-allowed':'Your browser’s speech service is unavailable. Use your keyboard’s dictation or type the story.'};
  const dictation=new Dictation({onState:state=>{active=state!=='idle';$('dictation-start').hidden=active;$('dictation-stop').hidden=!active;$('dictation-language').disabled=active;$('dictation-status').textContent=state==='starting'?'Starting microphone…':state==='listening'?'Listening — speech is being added as text.':'Dictation stopped.';$('dictate-toggle').setAttribute('aria-pressed',String(active));if(!active)void save();},onText:insertText,onInterim:text=>$('dictation-interim').textContent=text,onError:reason=>fail(errors[reason]||`Dictation stopped (${reason}). Your text is safe; try again or keep typing.`)});
  $('dictate-toggle').onclick=()=>{saveSelection();const show=$('dictation-panel').hidden;if(!show&&active)dictation.stop();$('dictation-panel').hidden=!show;$('dictate-toggle').setAttribute('aria-expanded',String(show));if(show){$('dictation-start').disabled=!supported;$('dictation-status').textContent=supported?'Ready. Place the cursor where the next words should go.':'Browser dictation is unavailable here. Type or use your keyboard’s dictation.';}};
  $('dictation-start').onclick=()=>{fail('');if(isRecording()){fail('Stop the audio recording before starting dictation.');return;}if(!navigator.onLine){fail('Browser dictation may need an internet connection. Your draft still saves locally.');return;}try{dictation.start($('dictation-language').value);}catch(e){fail(e.message);}};
  $('dictation-stop').onclick=()=>dictation.stop();
  document.addEventListener('visibilitychange',()=>{if(document.hidden&&active)dictation.stop();});
  return {active:()=>active,stop:()=>dictation.stop(),abort:()=>dictation.abort(),supported};
}
